import { createServer } from 'node:http';
    import { once } from 'node:events';
    import { DatabaseSync } from 'node:sqlite';

    function send(res, status, value) {
      res.writeHead(status, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(value));
    }

    async function body(req) {
      const chunks = [];
      for await (const chunk of req) chunks.push(chunk);
      return JSON.parse(Buffer.concat(chunks).toString('utf8'));
    }

async function handle(req, res, repo) { send(res, 404, { error: 'Not found' }); }

node.verification:
import { strict as assert } from 'node:assert';
const db = new DatabaseSync(':memory:');
    db.exec('CREATE TABLE notes (id INTEGER PRIMARY KEY, title TEXT NOT NULL)');
    const repo = {
      add(title) { return Number(db.prepare('INSERT INTO notes(title) VALUES (?)').run(title).lastInsertRowid); },
      list() { return db.prepare('SELECT id, title FROM notes ORDER BY id').all(); },
    };
    const server = createServer((req, res) => {
      Promise.resolve().then(() => handle(req, res, repo)).catch(() => {
        if (!res.headersSent) send(res, 500, { error: 'Internal server error' });
        else res.destroy();
      });
    }).listen(0, '127.0.0.1');
    try {
      await once(server, 'listening');
      const base = 'http://127.0.0.1:' + server.address().port;
      const post = body => fetch(base + '/notes', { method: 'POST', body });
      const created = await post('{"title":"  Learn Node  "}');
      assert.equal(created.status, 201);
      assert.deepEqual(await created.json(), { id: 1, title: 'Learn Node' });
      const result = await fetch(base + '/notes?display=all');
      assert.equal(result.status, 200);
      assert.deepEqual(await result.json(), [{ id: 1, title: 'Learn Node' }]);
      for (const invalid of ['{', 'null', '{"title":"  "}', JSON.stringify({ title: 'a'.repeat(81) })]) {
        assert.equal((await post(invalid)).status, 400);
      }
      assert.equal((await fetch(base + '/notes', { method: 'DELETE' })).status, 405);
      assert.equal((await fetch(base + '/missing')).status, 404);
      assert.equal(repo.list().length, 1);
    } finally {
      server.close();
      db.close();
    }
console.log("Все проверки пройдены.");
